         path=["r.24 appellate authority", "immediate superior for Group ‘C’", "wrong forum", "time spent there — sufficient cause", "entertain the appeal"],
         steps=[["Issue", "Appeal filed before the wrong authority and re-filed after return", "24, 25", 1],
                ["The forum", "For a Group ‘C’ employee the appellate authority is the authority to which the authority making the order is immediately subordinate, unless the Schedule or an order specifies otherwise", "24(1)(ii)", 2],
                ["Limitation", "The 45 days run from delivery of the order; filing before a wrong authority does not stop time", "25", 2],
                ["But sufficient cause", "Prosecuting a remedy before a forum that the appellant bona fide believed competent is a classic sufficient cause; the delay is explained and short", "proviso to 25", 3],
                ["Cure", "The appellate authority should condone the delay for the period between the wrong filing and the return, record its satisfaction and hear the appeal on merits", "proviso to 25", 1]],
